SELECT B.POSITION_ID as id,B.PARENT_ID,B.NAME,B.POS_RANK,B.ROLETYPE_ID,B.CREATE_TIME,B.PRIORITY
, ROLETYPE.NAME as roletypeName
FROM SYS_POSITION B
left join SYS_POSITION POS on B.PARENT_ID = POS.POSITION_ID
left join CORE_ROLETYPE ROLETYPE on B.ROLETYPE_ID = ROLETYPE.ROLETYPE_ID
left join CORE_POSTYPE POSTYPE on B.POSTYPE_ID =POSTYPE.POSTYPE_ID
where 1 = 1

    AND B.PARENT_ID is null


    AND B.PARENT_ID =#{parentId}


    AND B.NAME like  concat('%', #{name},'%')


    AND B.POS_RANK = #{posRank}


    AND B.ROLETYPE_ID = #{roletypeId}


    AND B.CREATE_TIME like  concat('%', #{createTime},'%')


     AND date_format(B.CREATE_TIME,'%Y-%m-%d') >= #{startTime}
AND date_format(B.CREATE_TIME,'%Y-%m-%d') <= #{endTime} 

ORDER BY PRIORITY ASC

SELECT B.POSITION_ID as id,B.PARENT_ID,B.NAME,B.POS_RANK,B.ROLETYPE_ID,B.CREATE_TIME,B.PRIORITY
, ROLETYPE.NAME as roletypeName
FROM
SYS_POSITION B
left join CORE_ROLETYPE ROLETYPE on B.ROLETYPE_ID = ROLETYPE.ROLETYPE_ID
where 1 = 1

    AND B.NAME like  concat('%', #{name},'%')


    AND B.POS_RANK = #{posRank}


    AND B.ROLETYPE_ID = #{roletypeId}


    AND B.CREATE_TIME like  concat('%', #{createTime},'%')


    and  B.ROLETYPE_ID=#{parentId}


     AND date_format(B.CREATE_TIME,'%Y-%m-%d') >= #{startTime}
    AND date_format(B.CREATE_TIME,'%Y-%m-%d') <= #{endTime} 

ORDER BY PRIORITY ASC

SELECT  POS.POSITION_ID as id,POS.PARENT_ID,POS.NAME,POS.POS_RANK,POS.CREATE_TIME,POS.PRIORITY
, ROLETYPE.NAME as roletypeName
FROM SYS_ROLE_POSITION B
LEFT JOIN SYS_POSITION POS ON B.POSITION_ID = POS.POSITION_ID
LEFT JOIN CORE_ROLETYPE ROLETYPE ON POS.ROLETYPE_ID = ROLETYPE.ROLETYPE_ID
where 1=1

    AND POS.NAME like  concat('%', #{name},'%')


    AND POS.POS_RANK = #{posRank}


    AND POS.ROLETYPE_ID = #{roletypeId}


    AND POS.CREATE_TIME like  concat('%', #{createTime},'%')


    and  B.ROLE_ID=#{parentId}


     AND date_format(B.CREATE_TIME,'%Y-%m-%d') >= #{startTime}
    AND date_format(B.CREATE_TIME,'%Y-%m-%d') <= #{endTime} 

ORDER BY PRIORITY ASC

